checking#r27.form:
shall [x1: interpreter "the interpreter the request is answered with" (indexical), x2: agent `clingo` (constant), x4: agent the person (constant), x5: specification "the specification of this bounded context" (indexical), x6: service the specification service (constant), x7: thing `0 violations` (parameter)]
  while [x3: interpreter]
    not
      import(subject: x1, object: x2)
    distinct(x3, x1)
    import(subject: x3, object: x2)
  when
    request(e1, specification.check, subject: x4, object: x5)
  response
    return(e2, subject: x6, object: x7)

items#r26.form:
shall [x2: agent the person (constant), x3: backlog "the backlog of this bounded context" (indexical), x4: service the backlog service (constant)]
  while [x1: item]
    exists(x1)
  when
    request(e1, backlog.list, subject: x2, object: x3)
  response [x5: title, x6: status, x7: provenance, x8: value, x9: urgency, x10: size]
    return(e2, subject: x4, object: x1)
    of(x5, x1)
    return(e3, subject: x4, object: x5)
    status(x1) = x6
    return(e4, subject: x4, object: x6)
    provenance(x1) = x7
    return(e5, subject: x4, object: x7)
    value(x1) = x8
    return(e6, subject: x4, object: x8)
    urgency(x1) = x9
    return(e7, subject: x4, object: x9)
    size(x1) = x10
    return(e8, subject: x4, object: x10)

measurement#r10.form:
shall [x1: agent the person (constant), x4: service the measurement service (constant)]
  when [x2: batch, x3: batch]
    distinct(x3, x2)
    request(e1, measurement.compare, subject: x1, object: x2, with: x3)
  response [x5: measurement, x6: measurement, x7: ratio]
    return(e2, subject: x4, object: x5)
    distinct(x6, x5)
    return(e3, subject: x4, object: x6)
    return(e4, subject: x4, object: x7)

measurement#r11.form:
shall [x1: agent the person (constant), x4: service the measurement service (constant)]
  when [x2: measurement, x3: measurement]
    distinct(x3, x2)
    request(e1, measurement.compare, subject: x1, object: x2, with: x3)
  response [x5: total row, x6: total row, x7: ratio]
    return(e2, subject: x4, object: x5)
    distinct(x6, x5)
    return(e3, subject: x4, object: x6)
    return(e4, subject: x4, object: x7)
